const decoders = Object.create(null);              // no prototype to collide with
decoders["order.created"]   = (b) => new OrderCreated(b.id, b.total);
decoders["order.cancelled"] = (b) => new OrderCancelled(b.id, b.reason);

const msg = JSON.parse(text);                      // the tag is just a field here
const decode = decoders[msg.type];
if (!decode) throw new UnknownTypeError(msg.type); // fail closed
return decode(msg.body);
